    #[test]
    fn savgol_filter_modes_match_scipy() {
        // scipy.signal.savgol_filter([1,2,4,7,11,16,22,29,37], 5, 2, mode=m).
        // frankenscipy-ckrdw: nearest/constant/mirror/wrap boundary parity.
        let x = vec![1.0, 2.0, 4.0, 7.0, 11.0, 16.0, 22.0, 29.0, 37.0];
        let want_nearest = [
            1.0857142857142847,
            1.9999999999999984,
            3.9999999999999973,
            6.9999999999999964,
            10.999999999999993,
            15.999999999999991,
            21.999999999999986,
            29.77142857142855,
            35.54285714285713,
        ];
        let want_mirror = [
            1.1714285714285702,
            1.9142857142857128,
            3.9999999999999973,
            6.9999999999999964,
            10.999999999999993,
            15.999999999999991,
            21.999999999999986,
            30.457142857142838,
            34.08571428571427,
        ];
        let want_wrap = [
            11.028571428571421,
            -1.0857142857142896,
            3.9999999999999973,
            6.9999999999999964,
            10.999999999999993,
            15.999999999999991,
            21.999999999999986,
            32.85714285714284,
            26.19999999999999,
        ];
        for (mode, want) in [
            (SavgolMode::Nearest, &want_nearest),
            (SavgolMode::Mirror, &want_mirror),
            (SavgolMode::Wrap, &want_wrap),
        ] {
            let got = savgol_filter_mode(&x, 5, 2, mode, 0.0).expect("filter");
            for (i, (&g, &w)) in got.iter().zip(want.iter()).enumerate() {
                assert!((g - w).abs() < 1e-9, "{mode:?}[{i}] = {g} != {w}");
            }
        }
        // constant mode honours cval (default 0.0 padding).
        let got_const = savgol_filter_mode(&x, 5, 2, SavgolMode::Constant, 0.0).expect("filter");
        assert!((got_const[0] - 0.8285714285714278).abs() < 1e-9);
    }

    #[test]
    fn savgol_filter_preserves_linear_including_edges() {
        // With mode='interp', a polynomial of degree <= polyorder is reproduced
        // exactly everywhere, edges included (unlike 'nearest').
        let x: Vec<f64> = (0..20).map(|i| 2.0 * i as f64 - 3.0).collect();
        let filtered = savgol_filter(&x, 5, 2).expect("filter");
        for (i, (&got, &want)) in filtered.iter().zip(x.iter()).enumerate() {
            assert!(
                (got - want).abs() < 1e-8,
                "filtered[{i}] = {got}, expected {want}"
            );
        }
    }

    #[test]
    fn savgol_filter_smooths_noise() {
        // Noisy signal should be smoothed
        let mut x: Vec<f64> = (0..50).map(|i| (i as f64 * 0.1).sin()).collect();
        // Add "noise"
        for (i, xi) in x.iter_mut().enumerate() {
            *xi += if i % 2 == 0 { 0.1 } else { -0.1 };
        }
        let filtered = savgol_filter(&x, 7, 3).expect("filter");
        // Filtered should have less variation than original
        let original_var: f64 = x.windows(2).map(|w| (w[1] - w[0]).powi(2)).sum();
        let filtered_var: f64 = filtered.windows(2).map(|w| (w[1] - w[0]).powi(2)).sum();
        assert!(
            filtered_var < original_var,
            "filtered should be smoother: {filtered_var} < {original_var}"
        );
    }

