    #[test]
    fn centered_window_percentiles_match_legacy_sort() {
        let row: Vec<f64> = (0..257)
            .map(|i| match i % 11 {
                0 => -0.0,
                1 => 0.0,
                2 => -3.5,
                _ => {
                    let x = i as f64;
                    (x * 0.17).sin() * 11.0 + (x * 0.031).cos() * 3.0
                }
            })
            .collect();

        for &window_size in &[0usize, 1, 2, 7, 16, 31, 64] {
            for &per in &[0.0, 10.0, 33.3, 50.0, 90.0, 100.0] {
                let got = centered_window_percentiles(&row, window_size, per);
                assert_eq!(got.len(), row.len());
                let hf_window = window_size / 2;
                let odd = window_size % 2;
                for (ind, &actual) in got.iter().enumerate() {
                    let start = ind.saturating_sub(hf_window);
                    let end = (ind + hf_window + odd).min(row.len());
                    let expected = score_at_percentile_linear_legacy_sort(&row[start..end], per);
                    assert_eq!(
                        actual.to_bits(),
                        expected.to_bits(),
                        "window_size={window_size} per={per} ind={ind}"
                    );
                }
            }
        }
    }

    #[test]
    fn find_peaks_cwt_matches_scipy() {
        // Same formula scipy oracle used (regenerated bit-for-bit in Rust).
        let data: Vec<f64> = (0..200)
            .map(|i| {
                let x = i as f64;
                (-((x - 30.0).powi(2)) / (2.0 * 25.0)).exp()
                    + 0.8 * (-((x - 90.0).powi(2)) / (2.0 * 64.0)).exp()
                    + 1.2 * (-((x - 150.0).powi(2)) / (2.0 * 36.0)).exp()
            })
            .collect();
        let widths: Vec<f64> = (1..=20).map(|i| i as f64).collect();

        let def = find_peaks_cwt(&data, &widths, &FindPeaksCwtOptions::default());
        assert_eq!(def, vec![30, 57, 90, 122, 151]);

        let snr2 = find_peaks_cwt(
            &data,
            &widths,
            &FindPeaksCwtOptions {
                min_snr: 2.0,
                ..Default::default()
            },
        );
        assert_eq!(snr2, vec![30, 57, 122, 151]);

        let ml5 = find_peaks_cwt(
            &data,
            &widths,
            &FindPeaksCwtOptions {
                min_length: Some(5),
                ..Default::default()
            },
        );
        assert_eq!(ml5, vec![30, 57, 90, 122, 151]);
    }

    #[test]
    fn lti_classes_match_scipy() {
        // H(s) = (s^2 + 3s + 3) / (s^2 + 2s + 1).
        let tf = TransferFunction::new(vec![1.0, 3.0, 3.0], vec![1.0, 2.0, 1.0]).unwrap();

        // to_zpk: zeros -1.5 +/- 0.8660254j, poles -1,-1, gain 1.
        let zpk = tf.to_zpk().unwrap();
        assert!((zpk.zpk.gain - 1.0).abs() < 1e-9);
        let mut zr = zpk.zpk.zeros_re.clone();
        zr.sort_by(f64::total_cmp);
        for z in &zr {
            assert!((z + 1.5).abs() < 1e-7, "zero re {z}");
        }
        let mut zi = zpk.zpk.zeros_im.clone();
        zi.sort_by(f64::total_cmp);
        assert!((zi[0] + 0.8660254).abs() < 1e-6 && (zi[1] - 0.8660254).abs() < 1e-6);
        for p in &zpk.zpk.poles_re {
            assert!((p + 1.0).abs() < 1e-6, "pole re {p}");
        }

        // to_ss then back to_tf round-trips to the original TF.
        let ss = tf.to_ss().unwrap();
        let tf2 = ss.to_tf().unwrap();
        for (a, b) in tf2.num.iter().zip(&[1.0, 3.0, 3.0]) {
            assert!((a - b).abs() < 1e-7, "ss2tf num {a} vs {b}");
        }
        for (a, b) in tf2.den.iter().zip(&[1.0, 2.0, 1.0]) {
            assert!((a - b).abs() < 1e-7, "ss2tf den {a} vs {b}");
        }

        // ZerosPolesGain.to_tf recovers the numerator/denominator.
        let tf3 = zpk.to_tf();
        for (a, b) in tf3.num.iter().zip(&[1.0, 3.0, 3.0]) {
            assert!((a - b).abs() < 1e-7, "zpk2tf num {a} vs {b}");
        }
        // StateSpace.to_zpk matches tf.to_zpk poles.
        let ssz = ss.to_zpk().unwrap();
        assert_eq!(ssz.zpk.poles_re.len(), 2);
    }

    #[test]
    fn choose_conv_method_matches_scipy() {
        // Result depends only on shapes, so dummy data of the right length works.
        let mk = |n: usize| vec![0.0_f64; n];
        // scipy.signal.choose_conv_method oracle (full): direct up to ~2000, fft from ~3000.
        assert_eq!(
            choose_conv_method(&mk(2000), &mk(2000), ConvolveMode::Full),
            ConvMethod::Direct
        );
        assert_eq!(
            choose_conv_method(&mk(3000), &mk(3000), ConvolveMode::Full),
            ConvMethod::Fft
        );
        assert_eq!(
            choose_conv_method(&mk(50), &mk(5), ConvolveMode::Full),
            ConvMethod::Direct
        );
        // valid mode
        assert_eq!(
            choose_conv_method(&mk(100000), &mk(5), ConvolveMode::Valid),
            ConvMethod::Direct
        );
        assert_eq!(
            choose_conv_method(&mk(100000), &mk(50000), ConvolveMode::Valid),
            ConvMethod::Fft
        );
        // same mode
        assert_eq!(
            choose_conv_method(&mk(100), &mk(100), ConvolveMode::Same),
            ConvMethod::Direct
        );
    }

