    // ── Periodogram tests ──────────────────────────────────────────

    #[test]
    fn periodogram_single_frequency() {
        // Pure sine wave at 10 Hz, sampled at 100 Hz
        let fs = 100.0;
        let freq = 10.0;
        let n = 256;
        let x: Vec<f64> = (0..n)
            .map(|i| (2.0 * std::f64::consts::PI * freq * i as f64 / fs).sin())
            .collect();

        let result = periodogram(&x, fs, None).expect("periodogram");
        assert_eq!(result.frequencies.len(), result.psd.len());
        assert!(!result.psd.is_empty());

        // Peak should be near 10 Hz
        let peak_idx = result
            .psd
            .iter()
            .enumerate()
            .max_by(|a, b| a.1.total_cmp(b.1))
            .map(|(i, _)| i)
            .unwrap();
        let peak_freq = result.frequencies[peak_idx];
        assert!(
            (peak_freq - freq).abs() < 1.0,
            "peak at {peak_freq} Hz, expected ~{freq} Hz"
        );
    }

    #[test]
    fn periodogram_with_hann_window() {
        let fs = 100.0;
        let n = 128;
        let x: Vec<f64> = (0..n)
            .map(|i| (2.0 * std::f64::consts::PI * 5.0 * i as f64 / fs).sin())
            .collect();
        let window = hann(n);
        let result = periodogram(&x, fs, Some(&window)).expect("periodogram");
        assert_eq!(result.psd.len(), n / 2 + 1);
        assert!(result.psd.iter().all(|v| v.is_finite() && *v >= 0.0));
    }

    #[test]
    fn periodogram_empty_rejected() {
        assert!(periodogram(&[], 1.0, None).is_err());
    }

    #[test]
    fn periodogram_rejects_invalid_window_coefficients() {
        let x = [0.0, 1.0, 0.0, -1.0];
        let nan_window = [1.0, f64::NAN, 1.0, 1.0];
        let inf_window = [1.0, 1.0, f64::INFINITY, 1.0];
        for window in [&nan_window[..], &inf_window[..]] {
            let err = periodogram(&x, 8.0, Some(window)).expect_err("invalid window");
            assert_eq!(
                err,
                SignalError::InvalidParameter {
                    detail: "window coefficients must be finite".to_string()
                }
            );
        }

        let zero_window = [0.0; 4];
        let err = periodogram(&x, 8.0, Some(&zero_window)).expect_err("zero-power window");
        assert_eq!(
            err,
            SignalError::InvalidParameter {
                detail: "window power must be positive".to_string()
            }
        );

        let short_window = [1.0, 1.0];
        let err = periodogram(&x, 8.0, Some(&short_window)).expect_err("short window");
        assert_eq!(
            err,
            SignalError::InvalidArgument(
                "window length (2) must match signal length (4)".to_string()
            )
        );
    }

    #[test]
    fn periodogram_rejects_non_finite_samples() {
        for x in [[0.0, f64::NAN, 1.0, -1.0], [0.0, f64::INFINITY, 1.0, -1.0]] {
            let err = periodogram(&x, 8.0, None).expect_err("non-finite samples");
            assert_eq!(
                err,
                SignalError::NonFiniteInput {
                    detail: "spectral input samples must be finite".to_string()
                }
            );
        }
    }

    #[test]
    fn spectral_estimators_reject_invalid_sampling_frequency() {
        fn assert_invalid_fs(err: SignalError, label: &str) {
            assert!(
                matches!(
                    err,
                    SignalError::InvalidParameter { ref detail } if detail.contains("fs")
                ),
                "{label} should reject invalid fs"
            );
        }

        let x = [0.0, 1.0, 0.5, -0.25, 0.25, -0.5, 1.5, 0.75];
        for fs in [0.0, -1.0, f64::INFINITY, f64::NAN] {
            assert_invalid_fs(
                periodogram(&x, fs, None).expect_err("periodogram should reject invalid fs"),
                "periodogram",
            );
            assert_invalid_fs(
                welch(&x, fs, None, Some(4), Some(2)).expect_err("welch should reject invalid fs"),
                "welch",
            );
            assert_invalid_fs(
                csd(&x, &x, fs, None, Some(4), Some(2)).expect_err("csd should reject invalid fs"),
                "csd",
            );
            assert_invalid_fs(
                coherence(&x, &x, fs, None, Some(4), Some(2))
                    .expect_err("coherence should reject invalid fs"),
                "coherence",
            );
            assert_invalid_fs(
                stft(&x, fs, None, Some(4), Some(2)).expect_err("stft should reject invalid fs"),
                "stft",
            );
            assert_invalid_fs(
                spectrogram(&x, fs, None, Some(4), Some(2))
                    .expect_err("spectrogram should reject invalid fs"),
                "spectrogram",
            );
        }
    }

