    #[test]
    fn resample_axis_2d_matches_serial_loop_bit_for_bit() {
        // resample_axis_2d must be bit-identical to the serial per-line resample
        // (parallel-across-lines is an order-preserving map).
        let mut s = 0x1234_5678_9abc_def1u64;
        let mut rng = || {
            s ^= s << 13;
            s ^= s >> 7;
            s ^= s << 17;
            (s >> 11) as f64 / (1u64 << 53) as f64 - 0.5
        };
        let nsig = 40usize;
        let l = 128usize;
        let num = 96usize;
        let x: Vec<Vec<f64>> = (0..nsig).map(|_| (0..l).map(|_| rng()).collect()).collect();
        // axis = -1: each row resampled to `num`.
        let many = resample_axis_2d(&x, num, -1).expect("resample_axis_2d");
        assert_eq!(many.len(), nsig);
        for (row, got) in x.iter().zip(&many) {
            let serial = resample(row, num).expect("resample");
            assert_eq!(got.len(), num);
            for (&g, &sref) in got.iter().zip(&serial) {
                assert_eq!(g.to_bits(), sref.to_bits(), "resample_axis_2d mismatch");
            }
        }
        // axis = 0: each column resampled to `num` -> output num rows x nsig cols.
        let by_col = resample_axis_2d(&x, num, 0).expect("resample_axis_2d axis0");
        assert_eq!(by_col.len(), num);
        for col in 0..l.min(x[0].len()) {
            let column: Vec<f64> = x.iter().map(|r| r[col]).collect();
            let serial = resample(&column, num).expect("resample col");
            for (row_idx, &sref) in serial.iter().enumerate() {
                assert_eq!(by_col[row_idx][col].to_bits(), sref.to_bits());
            }
        }
        // Empty batch -> empty result.
        assert!(resample_axis_2d(&[], num, -1).expect("empty").is_empty());
    }

    #[test]
    fn hilbert_many_matches_serial_loop_bit_for_bit() {
        // hilbert_many must be bit-identical to the serial per-signal loop
        // (parallel-across-signals is an order-preserving map). Enough signals
        // and length to exercise the parallel path (past the work gate).
        let mut s = 0x9E3779B97F4A7C15u64;
        let mut rng = || {
            s ^= s << 13;
            s ^= s >> 7;
            s ^= s << 17;
            (s >> 11) as f64 / (1u64 << 53) as f64 - 0.5
        };
        let nsig = 200usize;
        let signals: Vec<Vec<f64>> = (0..nsig)
            .map(|k| {
                // mixed even/odd lengths
                let len = if k % 2 == 0 { 256 } else { 129 };
                (0..len).map(|_| rng()).collect()
            })
            .collect();
        let many = hilbert_many(&signals).expect("hilbert_many");
        assert_eq!(many.len(), nsig);
        for (sig, got) in signals.iter().zip(&many) {
            let serial = hilbert(sig).expect("hilbert");
            assert_eq!(got.len(), serial.len());
            for (&(gr, gi), &(sr, si)) in got.iter().zip(&serial) {
                assert_eq!(gr.to_bits(), sr.to_bits(), "hilbert_many re mismatch");
                assert_eq!(gi.to_bits(), si.to_bits(), "hilbert_many im mismatch");
            }
        }
        // Empty batch -> empty result.
        assert!(hilbert_many(&[]).expect("empty batch").is_empty());
    }

    #[test]
    fn hilbert_dc_signal() {
        // DC signal: Hilbert transform of constant is zero
        let x = vec![5.0; 64];
        let analytic = hilbert(&x).expect("hilbert dc");
        // Imaginary parts should be ~0 for constant input
        for (i, &(_, im)) in analytic.iter().enumerate() {
            assert!(im.abs() < 1e-10, "DC imaginary[{i}] = {im}, expected ~0");
        }
    }

    // ── Notch/peak filter tests ──────────────────────────────────────

    #[test]
    fn iirnotch_rejects_target_frequency() {
        let coeffs = iirnotch(0.3, 30.0).expect("iirnotch");
        let result = freqz(&coeffs.b, &coeffs.a, Some(1024)).expect("freqz");
        // Find response at notch frequency (0.3π)
        let notch_idx = nearest_freq_index(&result.w, 0.3 * std::f64::consts::PI);
        // Response at notch should be near zero
        assert!(
            result.h_mag[notch_idx] < 0.1,
            "notch should attenuate target freq: mag = {}",
            result.h_mag[notch_idx]
        );
        // Response away from notch should be near 1
        let pass_idx = nearest_freq_index(&result.w, 0.1 * std::f64::consts::PI);
        assert!(
            result.h_mag[pass_idx] > 0.9,
            "passband should be near unity: mag = {}",
            result.h_mag[pass_idx]
        );
    }

    #[test]
    fn iirpeak_boosts_target_frequency() {
        let coeffs = iirpeak(0.3, 30.0).expect("iirpeak");
        let result = freqz(&coeffs.b, &coeffs.a, Some(1024)).expect("freqz");
        let peak_idx = nearest_freq_index(&result.w, 0.3 * std::f64::consts::PI);
        let pass_idx = nearest_freq_index(&result.w, 0.1 * std::f64::consts::PI);
        assert!(
            result.h_mag[peak_idx] > result.h_mag[pass_idx] * 2.0,
            "peak should boost target: peak={}, pass={}",
            result.h_mag[peak_idx],
            result.h_mag[pass_idx]
        );
    }

    #[test]
    fn iirnotch_iirpeak_match_scipy_orfanidis_design() {
        // Reference coefficients from scipy.signal.iirnotch / iirpeak.
        let check = |label: &str, got: &[f64], want: &[f64]| {
            for (g, w) in got.iter().zip(want.iter()) {
                assert!((g - w).abs() < 1e-12, "{label}: {g} != {w}");
            }
        };

        let notch = iirnotch(0.25, 5.0).expect("iirnotch");
        check(
            "notch_b",
            &notch.b,
            &[
                0.927_040_342_731_733_3,
                -1.311_033_025_558_219_7,
                0.927_040_342_731_733_3,
            ],
        );
        check(
            "notch_a",
            &notch.a,
            &[1.0, -1.311_033_025_558_219_7, 0.854_080_685_463_466_6],
        );

        let peak = iirpeak(0.25, 5.0).expect("iirpeak");
        check(
            "peak_b",
            &peak.b,
            &[0.072_959_657_268_266_7, 0.0, -0.072_959_657_268_266_7],
        );
        // notch and peak share the same denominator.
        check("peak_a", &peak.a, &notch.a);

        let notch2 = iirnotch(0.1, 2.0).expect("iirnotch");
        check(
            "notch2_b",
            &notch2.b,
            &[
                0.927_040_342_731_733_3,
                -1.763_335_517_647_015,
                0.927_040_342_731_733_3,
            ],
        );
    }

