    #[test]
    fn czt_rejects_invalid_polar_controls() {
        let x = [1.0, 2.0, 3.0];
        let invalid_controls = [
            (0.0, 0.0),
            (-1.0, 0.0),
            (f64::NAN, 0.0),
            (1.0, f64::NAN),
            (f64::INFINITY, 0.0),
            (1.0, f64::NEG_INFINITY),
        ];
        for control in invalid_controls {
            let err = czt(&x, 3, Some(control), None).expect_err("invalid w");
            assert_eq!(
                err,
                SignalError::InvalidParameter {
                    detail: "w magnitude must be finite and positive and angle must be finite"
                        .to_string()
                },
                "w={control:?}"
            );
            let err = czt(&x, 3, None, Some(control)).expect_err("invalid a");
            assert_eq!(
                err,
                SignalError::InvalidParameter {
                    detail: "a magnitude must be finite and positive and angle must be finite"
                        .to_string()
                },
                "a={control:?}"
            );
        }
    }

    #[test]
    fn remez_lowpass_filter() {
        // Design a 31-tap lowpass filter with cutoff at 0.2
        let h = remez(31, &[0.0, 0.15, 0.25, 0.5], &[1.0, 0.0], None).unwrap();
        assert_eq!(h.len(), 31);

        // Filter should be symmetric (linear phase)
        for i in 0..15 {
            assert!(
                (h[i] - h[30 - i]).abs() < 1e-10,
                "h[{i}] = {} != h[{}] = {}",
                h[i],
                30 - i,
                h[30 - i]
            );
        }

        // Sum of coefficients should approximate passband gain (1.0)
        let sum: f64 = h.iter().sum();
        assert!(sum > 0.5 && sum < 1.5, "filter sum = {sum}, expected ~1.0");
    }

    #[test]
    fn remez_differentiator_response_proportional_to_frequency() {
        use std::f64::consts::PI;
        // Differentiator: antisymmetric FIR with response A(f) ∝ f and a 1/f
        // (relative-error) weight — the canonical McClellan-Parks-Rabiner
        // convention scipy ports. Unique minimax => equiripple relative error
        // proves it. No in-env scipy oracle, so we verify the defining
        // properties: antisymmetric, A(f)/f ≈ desired, equiripple relative error.
        for &numtaps in &[15usize, 16usize] {
            let odd = numtaps % 2 == 1;
            let bands = if odd { [0.0, 0.45] } else { [0.0, 0.5] };
            let h = remez_with_type(
                numtaps,
                &bands,
                &[1.0],
                None,
                RemezFilterType::Differentiator,
            )
            .unwrap();
            assert_eq!(h.len(), numtaps);
            for n in 0..numtaps {
                assert!(
                    (h[n] + h[numtaps - 1 - n]).abs() < 1e-12,
                    "differentiator taps must be antisymmetric at {n} (numtaps={numtaps})"
                );
            }
            let mag = |f: f64| -> f64 {
                let (mut re, mut im) = (0.0f64, 0.0f64);
                for (n, &hn) in h.iter().enumerate() {
                    let ang = 2.0 * PI * f * n as f64;
                    re += hn * ang.cos();
                    im -= hn * ang.sin();
                }
                (re * re + im * im).sqrt()
            };
            // Response proportional to frequency: |H(f)|/f ≈ 1, equiripple.
            // Sample away from DC (relative error is noisy as f→0) up to the band
            // edge (just inside Nyquist for the odd/Type-III forced zero).
            let hi = bands[1] - if odd { 0.0 } else { 1e-9 };
            let (lo, top) = (0.05, (hi - 0.02).max(0.1));
            let nq = 6000usize;
            let mut over = 0.0f64;
            let mut under = 0.0f64;
            for i in 0..=nq {
                let f = lo + (top - lo) * i as f64 / nq as f64;
                let rel = mag(f) / f - 1.0; // desired = 1
                over = over.max(rel);
                under = under.max(-rel);
            }
            assert!(
                over < 0.1 && under < 0.1,
                "differentiator |H|/f deviates too much (numtaps={numtaps}): over {over} under {under}"
            );
            assert!(
                (over - under).abs() <= 0.15 * over.max(under),
                "differentiator relative error not equiripple (numtaps={numtaps}): over {over} under {under}"
            );
        }
    }

    #[test]
    fn remez_hilbert_is_equiripple_antisymmetric() {
        use std::f64::consts::PI;
        // Hilbert transformer: unit-gain antisymmetric FIR over a band avoiding
        // DC (and Nyquist for odd numtaps). No scipy fixture in-env, but the
        // minimax optimum is unique, so equiripple |H|≈1 in-band proves parity.
        for &numtaps in &[15usize, 16usize] {
            let odd = numtaps % 2 == 1;
            // Type III (odd) forces a zero at Nyquist too, so keep the band away
            // from 0.5; Type IV (even) only needs to avoid DC.
            let bands = if odd { [0.05, 0.45] } else { [0.05, 0.5] };
            let h =
                remez_with_type(numtaps, &bands, &[1.0], None, RemezFilterType::Hilbert).unwrap();
            assert_eq!(h.len(), numtaps);
            // Antisymmetric taps.
            for n in 0..numtaps {
                assert!(
                    (h[n] + h[numtaps - 1 - n]).abs() < 1e-12,
                    "hilbert taps must be antisymmetric at {n} (numtaps={numtaps})"
                );
            }
            // |H(e^{jω})| magnitude response.
            let mag = |f: f64| -> f64 {
                let (mut re, mut im) = (0.0f64, 0.0f64);
                for (n, &hn) in h.iter().enumerate() {
                    let ang = 2.0 * PI * f * n as f64;
                    re += hn * ang.cos();
                    im -= hn * ang.sin();
                }
                (re * re + im * im).sqrt()
            };
            // Forced zeros.
            assert!(
                mag(0.0) < 1e-9,
                "Hilbert |H(0)| must be ~0 (numtaps={numtaps})"
            );
            if odd {
                assert!(
                    mag(0.5) < 1e-9,
                    "Type-III Hilbert |H(0.5)| must be ~0 (numtaps={numtaps})"
                );
            }
            // Equiripple about 1.0 in the band: max overshoot ≈ max undershoot.
            let (lo, hi) = (bands[0], bands[1]);
            let nq = 6000usize;
            let mut over = 0.0f64; // max (|H|-1)
            let mut under = 0.0f64; // max (1-|H|)
            for i in 0..=nq {
                let f = lo + (hi - lo) * i as f64 / nq as f64;
                let d = mag(f) - 1.0;
                over = over.max(d);
                under = under.max(-d);
            }
            assert!(
                (over - under).abs() <= 5e-2 * over.max(under),
                "Hilbert not equiripple (numtaps={numtaps}): over {over} vs under {under}"
            );
            // Genuine equiripple design, not a crude approximation.
            assert!(
                over < 0.1 && under < 0.1,
                "Hilbert band ripple too large (numtaps={numtaps}): over {over} under {under}"
            );
        }
    }

    #[test]
    fn firls_type2_is_least_squares_optimal() {
        use std::f64::consts::PI;
        // Type-II (even numtaps) least-squares lowpass. No scipy fixture in-env,
        // but the weighted-LS minimizer is UNIQUE, so verifying the optimality
        // condition ∫_bands W·(A-D)·cos(2πf(k-½)) df = 0 for every basis index k
        // proves it equals scipy.signal.firls. The condition is evaluated by
        // numerical quadrature on the ACTUAL designed response — independent of
        // the closed-form normal-equation integrals used to build it.
        let numtaps = 12usize;
        let m = numtaps / 2;
        let bands = [0.0, 0.4, 0.5, 1.0]; // Nyquist-normalized; passband 1, stop 0
        let desired = [1.0, 1.0, 0.0, 0.0];
        let h = firls(numtaps, &bands, &desired, None).unwrap();
        assert_eq!(h.len(), numtaps);
        for n in 0..numtaps {
            assert!(
                (h[n] - h[numtaps - 1 - n]).abs() < 1e-12,
                "type-II firls taps must be symmetric at {n}"
            );
        }
        // Zero-phase amplitude A(f) = Σ h[n] cos(2πf(n-(N-1)/2)).
        let c = (numtaps as f64 - 1.0) / 2.0;
        let amp = |f: f64| -> f64 {
            (0..numtaps)
                .map(|n| h[n] * (2.0 * PI * f * (n as f64 - c)).cos())
                .sum()
        };
        // Desired (in [0,0.5] normalized) and per-band weight (all 1 here).
        let d_of = |f: f64| -> Option<f64> {
            if f <= 0.2 {
                Some(1.0)
            } else if f >= 0.25 {
                Some(0.0)
            } else {
                None // transition band: unconstrained
            }
        };
        // Optimality residual for each basis frequency (k-½), via dense quadrature.
        let nq = 200_000usize;
        for k in 1..=m {
            let ck = k as f64 - 0.5;
            let mut integral = 0.0f64;
            for i in 0..nq {
                let f = 0.5 * (i as f64 + 0.5) / nq as f64; // midpoint over [0,0.5]
                if let Some(d) = d_of(f) {
                    integral += (amp(f) - d) * (2.0 * PI * f * ck).cos();
                }
            }
            integral *= 0.5 / nq as f64;
            assert!(
                integral.abs() < 1e-4,
                "firls Type-II not LS-optimal: ∂/∂a_{k} residual = {integral}"
            );
        }
    }

    #[test]
    fn remez_type2_is_equiripple_optimal() {
        use std::f64::consts::PI;
        // Type-II (even numtaps) lowpass. No scipy fixture in-env, but the
        // minimax optimum is UNIQUE — an equiripple solution IS scipy's output.
        // So we prove correctness by the alternation signature: equal weighted
        // ripple across passband and stopband.
        let numtaps = 12usize;
        let h = remez(numtaps, &[0.0, 0.2, 0.3, 0.5], &[1.0, 0.0], None).unwrap();
        assert_eq!(h.len(), numtaps);
        // Type-II linear phase: symmetric taps.
        for n in 0..numtaps {
            assert!(
                (h[n] - h[numtaps - 1 - n]).abs() < 1e-12,
                "type-II taps must be symmetric at {n}"
            );
        }
        // Type-II forces A(0.5)=0 (Nyquist zero).
        let amp = |f: f64| -> f64 {
            let c = (numtaps as f64 - 1.0) / 2.0;
            (0..numtaps)
                .map(|n| h[n] * (2.0 * PI * f * (n as f64 - c)).cos())
                .sum()
        };
        assert!(amp(0.5).abs() < 1e-9, "Type-II A(0.5) must be ~0");
        // Sample passband [0,0.2] and stopband [0.3,0.5] densely; peak ripple
        // in each must match (unweighted equiripple => δ_pass == δ_stop).
        let n_samp = 8000usize;
        let mut dp = 0.0f64; // max |A-1| in passband
        let mut ds = 0.0f64; // max |A|   in stopband
        for i in 0..=n_samp {
            let f = 0.2 * i as f64 / n_samp as f64;
            dp = dp.max((amp(f) - 1.0).abs());
        }
        for i in 0..=n_samp {
            let f = 0.3 + 0.2 * i as f64 / n_samp as f64;
            ds = ds.max(amp(f).abs());
        }
        // Equiripple optimum: the two unweighted band ripples are equal (the
        // alternation/uniqueness signature). A loose least-squares design would
        // differ by >50%; equality to ~1% (the residual is test-grid resolution
        // vs the exchange's grid_density=16) proves the minimax solution.
        assert!(
            (dp - ds).abs() <= 1.5e-2 * dp.max(ds),
            "Type-II remez not equiripple: passband ripple {dp} vs stopband ripple {ds}"
        );
        // And it must be a genuine minimax design, not the loose LS fallback
        // (which left ~0.05+ ripple for this band layout).
        assert!(
            ds < 0.06,
            "Type-II stopband ripple {ds} too large (not minimax)"
        );
    }

    #[test]
    fn remez_matches_scipy_reference() {
        // True Parks-McClellan equiripple — matches scipy.signal.remez to
        // machine precision (the minimax optimum is unique). frankenscipy-zxxdi.
        let lp = remez(11, &[0.0, 0.2, 0.3, 0.5], &[1.0, 0.0], None).unwrap();
        let lp_want = [
            0.05372035912417292,
            -4.61214414692147e-05,
            -0.09157551252765038,
            -6.7107264123562e-05,
            0.31313220746845083,
            0.49991992278419434,
            0.31313220746845083,
            -6.7107264123562e-05,
            -0.09157551252765038,
            -4.61214414692147e-05,
            0.05372035912417292,
        ];
        for (got, want) in lp.iter().zip(lp_want.iter()) {
            assert!((got - want).abs() < 1e-9, "remez lp {got} != {want}");
        }

        // Bandpass + per-band weights [1,2,1].
        let bp = remez(
            25,
            &[0.0, 0.1, 0.2, 0.35, 0.4, 0.5],
            &[0.0, 1.0, 0.0],
            Some(&[1.0, 2.0, 1.0]),
        )
        .unwrap();
        let bp_want = [
            0.012060197241103647,
            0.04917749494274411,
            -0.007947334066976923,
            0.004452003914280255,
            -0.03892881686970368,
            -0.06476079736891961,
            0.05399001261854428,
            0.024180050124328233,
            0.06969629437057305,
            0.07480203046973387,
            -0.2969463360118628,
            -0.05746490861257541,
            0.4161519654366445,
            -0.05746490861257541,
            -0.2969463360118628,
            0.07480203046973387,
            0.06969629437057305,
            0.024180050124328233,
            0.05399001261854428,
            -0.06476079736891961,
            -0.03892881686970368,
            0.004452003914280255,
            -0.007947334066976923,
            0.04917749494274411,
            0.012060197241103647,
        ];
        for (got, want) in bp.iter().zip(bp_want.iter()) {
            assert!((got - want).abs() < 1e-9, "remez bp {got} != {want}");
        }
    }

