        // scipy.signal.windows.blackman(5)
        // -> [0., 0.34, 1., 0.34, 0.] approximately
        let w = blackman(5);
        assert_eq!(w.len(), 5);
        // First and last should be close to 0
        assert!(w[0].abs() < 0.01, "blackman(5)[0] should be ~0");
        assert!(w[4].abs() < 0.01, "blackman(5)[4] should be ~0");
