    #[test]
    fn bode_dbode_match_scipy() {
        // Continuous H(s) = (s+2)/(s^2+3s+2).
        let w = [0.1, 0.5, 1.0, 2.0, 5.0, 10.0];
        let (_, mag, ph) = bode(&[1.0, 2.0], &[1.0, 3.0, 2.0], &w).unwrap();
        let cmag = [
            -0.04321374,
            -0.96910013,
            -3.01029996,
            -6.98970004,
            -14.14973348,
            -20.04321374,
        ];
        let cpha = [
            -5.71059314,
            -26.56505118,
            -45.0,
            -63.43494882,
            -78.69006753,
            -84.28940686,
        ];
        for (g, e) in mag.iter().zip(&cmag) {
            assert!((g - e).abs() < 1e-6, "cmag {g} vs {e}");
        }
        for (g, e) in ph.iter().zip(&cpha) {
            assert!((g - e).abs() < 1e-6, "cpha {g} vs {e}");
        }
        // Discrete H(z) = (z+0.5)/(z^2-0.3z+0.1), dt=0.1; phase unwraps past -180.
        let wd = [0.1, 0.5, 1.0, 2.0, 3.0];
        let (_, dmag, dpha) = dbode(&[1.0, 0.5], &[1.0, -0.3, 0.1], 0.1, &wd).unwrap();
        let dmexp = [5.45505269, 5.29335234, 4.33269855, -1.73705729, -8.74029528];
        let dpexp = [
            -8.36128602,
            -42.42298117,
            -87.08884395,
            -162.65824963,
            -182.72943349,
        ];
        for (g, e) in dmag.iter().zip(&dmexp) {
            assert!((g - e).abs() < 1e-6, "dmag {g} vs {e}");
        }
        for (g, e) in dpha.iter().zip(&dpexp) {
            assert!((g - e).abs() < 1e-6, "dpha {g} vs {e}");
        }
    }

    #[test]
    fn cspline1d_qspline1d_eval_match_scipy() {
        let s = [1.0, 2.0, 5.0, 3.0, 8.0, 4.0, 2.0, 6.0, 1.0, 7.0];
        let cj = cspline1d(&s, 0.0).unwrap();
        let qj = qspline1d(&s, 0.0).unwrap();
        // includes out-of-range points (mirror reflection) and an exact knot.
        let nx = [-1.3, 0.0, 2.7, 4.5, 9.0, 10.5];
        let ce = cspline1d_eval(&cj, &nx, 1.0, 0.0).unwrap();
        let cexp = [
            3.143115502,
            1.000004982,
            3.111312777,
            6.9312201046,
            7.0,
            3.3680427052,
        ];
        for (g, e) in ce.iter().zip(&cexp) {
            assert!((g - e).abs() < 1e-7, "cubic eval {g} vs {e}");
        }
        let qe = qspline1d_eval(&qj, &nx, 1.0, 0.0).unwrap();
        let qexp = [
            2.9780378835,
            1.000000032,
            3.0553399474,
            6.7111017662,
            7.0,
            3.3630423045,
        ];
        for (g, e) in qe.iter().zip(&qexp) {
            assert!((g - e).abs() < 1e-7, "quad eval {g} vs {e}");
        }
        assert!(cspline1d_eval(&[], &nx, 1.0, 0.0).is_err());
        assert_eq!(
            cspline1d_eval(&cj, &nx, 0.0, 0.0),
            Err(SignalError::InvalidArgument(
                "dx must be finite and nonzero".to_string()
            ))
        );
        assert_eq!(
            qspline1d_eval(&qj, &nx, f64::INFINITY, 0.0),
            Err(SignalError::InvalidArgument(
                "dx must be finite and nonzero".to_string()
            ))
        );
        assert_eq!(
            cspline1d_eval(&cj, &nx, f64::NAN, 0.0),
            Err(SignalError::InvalidArgument(
                "dx must be finite and nonzero".to_string()
            ))
        );
    }

    #[test]
    fn spline1d_eval_rejects_non_finite_inputs() {
        let cj = [1.0, 2.0, 3.0];
        let nx = [0.0, 1.0, 2.0];
        assert_eq!(
            cspline1d_eval(&[1.0, f64::NAN, 3.0], &nx, 1.0, 0.0),
            Err(SignalError::NonFiniteInput {
                detail: "cspline1d_eval coefficients must be finite".to_string(),
            })
        );
        assert_eq!(
            cspline1d_eval(&cj, &[0.0, f64::INFINITY], 1.0, 0.0),
            Err(SignalError::NonFiniteInput {
                detail: "cspline1d_eval coordinates must be finite".to_string(),
            })
        );
        assert_eq!(
            cspline1d_eval(&cj, &nx, 1.0, f64::NEG_INFINITY),
            Err(SignalError::NonFiniteInput {
                detail: "cspline1d_eval x0 must be finite".to_string(),
            })
        );
        assert_eq!(
            qspline1d_eval(&[1.0, f64::INFINITY, 3.0], &nx, 1.0, 0.0),
            Err(SignalError::NonFiniteInput {
                detail: "qspline1d_eval coefficients must be finite".to_string(),
            })
        );
        assert_eq!(
            qspline1d_eval(&cj, &[0.0, f64::NAN], 1.0, 0.0),
            Err(SignalError::NonFiniteInput {
                detail: "qspline1d_eval coordinates must be finite".to_string(),
            })
        );
        assert_eq!(
            qspline1d_eval(&cj, &nx, 1.0, f64::INFINITY),
            Err(SignalError::NonFiniteInput {
                detail: "qspline1d_eval x0 must be finite".to_string(),
            })
        );
    }

    #[test]
    fn cspline1d_qspline1d_match_scipy() {
        let s = [1.0, 2.0, 5.0, 3.0, 8.0, 4.0, 2.0, 6.0, 1.0, 7.0];
        let c = cspline1d(&s, 0.0).unwrap();
        let cexp = [
            1.0159134252,
            0.9204627659,
            7.3022355113,
            -0.129404811,
            11.2153837329,
            3.2678698795,
            -0.2868632507,
            9.8795831234,
            -3.231469243,
            9.0462938486,
        ];
        for (g, e) in c.iter().zip(&cexp) {
            assert!((g - e).abs() < 1e-8, "cubic {g} vs {e}");
        }
        let q = qspline1d(&s, 0.0).unwrap();
        let qexp = [
            0.9316946252,
            1.4781378801,
            6.1994780944,
            1.3249935538,
            9.8505605828,
            3.5716429497,
            0.7195817193,
            8.1108667343,
            -1.3847821254,
            8.1978260179,
        ];
        for (g, e) in q.iter().zip(&qexp) {
            assert!((g - e).abs() < 1e-8, "quad {g} vs {e}");
        }
        // Smoothing branch is rejected.
        assert!(cspline1d(&s, 1.0).is_err());
    }

